import{_ as t,l as o,o as e,c as n,v as l,p as s,x as i,d as p,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"氢起泡","description":"","frontmatter":{"title":"氢起泡","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/hydrogen-blister.md","filePath":"litho/hydrogen-blister.md","lastUpdated":1789023840000}'),E={name:"litho/hydrogen-blister.md"};function c(B,a,A,_,m,u){const r=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=l('<h1 id="氢起泡" tabindex="-1">氢起泡 <a class="header-anchor" href="#氢起泡" aria-label="Permalink to &quot;氢起泡&quot;">​</a></h1><div class="epigraph"><p>氢自由基能把锡变成可抽走的氢化物，也能钻进多层膜和薄膜，聚成气泡把界面掀开。</p><footer>—— 对照 EUV 多层膜与 pellicle 在氢环境中起泡、分层的公开讨论；氢化学接口见 ASML DGL 叙述</footer></div><p><a href="/litho/euv-hydrogen-dgl">上一课</a>把氢写成缓冲气体兼原位清洗剂：EUV 解离 H₂，H 与 Sn、C 生成 SnH₄、CH₄。缺口是同一套自由基对 <a href="/litho/euv-multilayer-mirror">Mo/Si 多层</a> 和 <a href="/litho/euv-pellicle">pellicle</a> 并不只做好事。本课钉氢起泡（blistering）。镀上的锡如何与起泡叠加，留给<a href="/litho/tin-on-mirrors">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DGL 课已经说明惰性气体不把锡清走，量产必须用氢。氢原子半径小，能沿晶界、针孔和帽层缺陷植入 Mo/Si，在界面或周期膜里复合成 H₂。气泡一旦成核，局部应力把钌帽或硅层掀起，反射率掉、散射升、波前出指纹。清洗流量越大、EUV 越亮，自由基产量越高，这条损伤通道越醒。</p><p>Pellicle 更薄。公开讨论里，膜要在氢与 EUV 同时存在时保持透过率与机械完整；氢致起泡、脆化和针孔会把「挡颗粒」的膜变成二次污染源。缺口是：清洗化学与光学寿命必须写在同一张材料表上，不能默认「开氢就净」。</p><h3 id="起泡不是普通腐蚀" tabindex="-1">起泡不是普通腐蚀 <a class="header-anchor" href="#起泡不是普通腐蚀" aria-label="Permalink to &quot;起泡不是普通腐蚀&quot;">​</a></h3><p>氧化和水汽攻击帽层，是化学腐蚀加周期漂移。起泡是气体聚集体的力学失效：局部鼓包、分层、甚至剥落。氢刻蚀锡的反应在表面；起泡发生在膜内。把两者都叫做「氢损伤」，会把可逆清洗和不可逆分层混成一条维护工单。</p><p><span class="marginnote">投影 POB 的氢分压远低于光源舱，起泡风险主要在收集镜、光源侧多层和 pellicle。不要把收集镜氢洗的流量外推到蔡司投影镜腔。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>材料侧：帽层（公开讨论常见 Ru 一类）要挡植入又要让表面锡能被 H 抽走；周期膜的应力与界面要耐 H₂ 成核。工艺侧：氢流量、压力、温度和 EUV 开/关占空比构成窗口——流量过低锡累积，过高植入和起泡加速。停光时自由基少，有时要辅助解离，有时只能接受清洗暂停。</p><p>Pellicle 的公开规格同时写透过率、热和氢兼容。换膜材料等于重做氢窗口，不能把 DUV 有机膜的氢稳定性搬过来。量产叙述把氢兼容当成光学子系统资格认证的一部分，而不是后加的气氛。</p><h3 id="检测看鼓包与散射-不只看平均-r" tabindex="-1">检测看鼓包与散射，不只看平均 R <a class="header-anchor" href="#检测看鼓包与散射-不只看平均-r" aria-label="Permalink to &quot;检测看鼓包与散射，不只看平均 R&quot;">​</a></h3><p>平均反射率下降可能是均匀镀锡；起泡往往先出散射和局部相位。光化或高灵敏形貌才能把鼓包与均匀吸收分开。只盯 IF 瓦数，会把起泡误判成「再加点氢就会好」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>EUV 光子与等离子体电子都解离 H₂。H 在表面复合放热、与 Sn 反应，也向体内扩散。捕获位点（空位、界面、辐照缺陷）把 H 留下，浓度一过饱和就成泡。多层是现成的弱界面：Mo/Si 本身应力就高，再加氢，分层沿周期走。 pellicle 的多晶硅或后继膜种同样提供晶界通道。</p><p>起泡与剂量相关：亮场、高功率、长曝光日历累积。这和锡沉积的空间指纹不同——锡跟碎屑方向走，氢跟自由基通量和材料捕获走。</p><p><span class="marginnote">氢致损伤的公开文献覆盖多层帽层与 pellicle，不覆盖未公布的蔡司膜堆配方。本课只引用机制与工程取舍，不写某代 POB 的氢分压表。</span></p>',18)),(e(),s(d,null,{default:i(()=>[h(r,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20H2%5B%22H2%20%E7%BC%93%E5%86%B2%22%5D%20--%3E%20EUV%5B%22EUV%20%E8%A7%A3%E7%A6%BB%22%5D%0A%20%20EUV%20--%3E%20H%5B%22H%20%E8%87%AA%E7%94%B1%E5%9F%BA%22%5D%0A%20%20H%20--%3E%20CLEAN%5B%22SnH4%20%2F%20CH4%20%E6%8A%BD%E8%B5%B0%22%5D%0A%20%20H%20--%3E%20IMP%5B%22%E6%A4%8D%E5%85%A5%E5%A4%9A%E5%B1%82%20%2F%20%E8%96%84%E8%86%9C%22%5D%0A%20%20IMP%20--%3E%20BL%5B%22H2%20%E8%B5%B7%E6%B3%A1%E5%88%86%E5%B1%82%22%5D%0A%20%20BL%20--%3E%20SCAT%5B%22%E6%95%A3%E5%B0%84%E4%B8%8E%E6%B3%A2%E5%89%8D%E6%8C%87%E7%BA%B9%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重写气锁缝几何，也不把 pellicle 热预算展开。不要把实验室离子束氢辐照的起泡照片直接标成 NXE 投影镜的失效模式。后课默认：说到氢清洗，先问帽层和薄膜是否还在起泡窗口内侧。</p><p>未公开的抗氢镀膜工艺不要发明。引用停在 ASML 氢环境叙述与多层/pellicle 氢损伤的公开讨论。</p><p><span class="marginnote">起泡一旦分层，氢刻蚀抽不回周期结构。那是换件或报废，不是加大流量能洗掉的污染。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>清洗用的氢自由基也能植入 Mo/Si 与 pellicle，复合成泡并分层。</li><li>起泡是膜内力学失效，与表面锡的可逆氢刻蚀不是同一条工单。</li><li>流量窗口夹在「锡清不掉」和「植入起泡」之间。</li><li>平均反射率掩盖鼓包；要看散射与形貌。</li><li>出处：ASML 氢 / DGL 公开材料；EUV 多层与 pellicle 氢损伤公开讨论。</li></ul>',6))])}const b=t(E,[["render",c]]);export{S as __pageData,b as default};
